import {poems,pictures,radicals} from './literacy-data.js';
import {dailyPoem,checkPoem,draftKey} from './literacy-core.js';
import {localDay,shuffled} from './core.js';
export function createLiteracy({getState,persist,go,refresh,notify,play,esc,btn,icon}){
 const record=()=>getState().literacy;
 const visit=(tab,view='',id='',mode='next')=>go('literacy',{tab,view,id,mode});
 const tabs=[['poems','日常积累古诗词'],['dictation','古诗词默写'],['pictures','看图写话'],['radicals','部首偏旁']];
 const results=new Map();let quiz=null,paperReveal=null;
 const draft=key=>record().drafts[key]?.text||'';
 const back=tab=>btn(`${icon('back')}返回${tabs.find(t=>t[0]===tab)?.[1]||'语文积累'}`,'lit-tab','small',`data-tab="${tab}"`);
 const poemCard=(p,tab)=>`<button class="card link poem-card" data-action="lit-poem" data-id="${p.id}" data-tab="${tab}"><span class="row between"><span class="tag">${p.genre} · 课外积累</span>${record().learned[p.id]?'<span class="muted text-small">已标记熟读</span>':''}</span><h2>${p.title}</h2><span class="muted">${p.dynasty} · ${p.author}</span><span class="bottom">${tab==='dictation'?'开始默写':'读一读，慢听一句'} ${icon('arrow')}</span></button>`;
 function render(route){const tab=tabs.some(t=>t[0]===route.tab)?route.tab:'poems';let body;
  if(route.view==='poem'){const p=poems.find(p=>p.id===route.id)||dailyPoem(localDay());body=readPoem(p);}
  else if(route.view==='test'){const p=poems.find(p=>p.id===route.id)||poems[0];body=poemTest(p,route.mode);}
  else if(route.view==='picture'){const p=pictures.find(p=>p.id===route.id)||pictures[0];body=picturePage(p);}
  else if(route.view==='quiz'){if(!quiz)newQuiz();body=radicalQuiz();}
  else if(tab==='poems'){const p=dailyPoem(localDay());body=`<section class="study-launch mt"><div><div class="kicker">今天读一首 · 课外积累</div><h2>${p.title}</h2><p>${p.dynasty} · ${p.author} · 每天慢慢积累</p></div>${btn('开始读一读','lit-poem','primary',`data-id="${p.id}" data-tab="poems"`)}</section><div class="section-head"><h2>古诗词小书架</h2><span class="tip">${Object.keys(record().learned).length} / ${poems.length} 首已标记熟读</span></div><div class="grid three">${poems.map(p=>poemCard(p,'poems')).join('')}</div>`;}
  else if(tab==='dictation')body=`<div class="note-box mt">${icon('pencil')}<span>先自己回忆，再核对原文。输入汉字可自动核对文字；纸上默写需要自己或家长对照，不做手写识别。</span></div><div class="grid three mt">${poems.map(p=>poemCard(p,'dictation')).join('')}</div>`;
  else if(tab==='pictures')body=`<p class="tip mt">先观察，再说一说，最后写几句话。这里没有唯一答案，也不会自动给作文打分。</p><div class="grid two mt">${pictures.map(p=>`<button class="card link picture-card" data-action="lit-picture" data-id="${p.id}"><img src="${p.image}" alt="${esc(p.alt)}" width="800" height="480" loading="lazy"><h2>${p.title}</h2><span class="bottom">${draft(draftKey('picture',p.id))?'继续我的草稿':'看一看，写一写'} ${icon('arrow')}</span></button>`).join('')}</div>`;
  else body=radicalPage();
  return `<div class="headline"><div><div class="kicker">读一读 · 记一记 · 写一写</div><h1>语文积累</h1><p>每天积累一点，把会读变成会用。</p></div></div><div class="tabs literacy-tabs" aria-label="语文积累栏目">${tabs.map(([id,label])=>`<button data-action="lit-tab" data-tab="${id}" aria-pressed="${id===tab}" class="${id===tab?'selected':''}">${label}</button>`).join('')}</div>${body}`;
 }
 function readPoem(p){return `<div class="row mt">${back('poems')}</div><article class="card poem-sheet mt"><span class="tag">${p.genre} · 课外积累</span><h2>${p.title}</h2><p class="muted">${p.dynasty} · ${p.author}</p><div class="poem-lines">${p.lines.map((line,i)=>`<button class="poem-line" data-action="lit-speak" data-text="${esc(line)}" aria-label="慢听第${i+1}句：${esc(line)}"><span>${line}</span>${icon('sound')}</button>`).join('')}</div><p id="audio-status" class="listen-status" role="status">点一句慢慢听，再跟着读一遍。播放的是合成普通话。</p><div class="note-box mt">${icon('leaf')}<span>${p.note}</span></div><div class="practice-actions">${btn(record().learned[p.id]?'再标记一次熟读':'我已读熟，做个标记','lit-learned','primary',`data-id="${p.id}"`)}${btn('试试默写','lit-poem','',`data-id="${p.id}" data-tab="dictation"`)}</div><p class="tip mt-sm">熟读标记由自己或家长确认，不代表自动测评。</p><a class="text-small" href="${p.source}" target="_blank" rel="noopener noreferrer">查看原作文本依据 ↗</a></article>`;}
 function poemTest(p,rawMode){const mode=['next','full','paper'].includes(rawMode)?rawMode:'next';const key=draftKey('poem',p.id,mode);const text=draft(key);const result=results.get(key);const checked=result?.text===text;
  return `<div class="row mt">${back('dictation')}</div><section class="card mt"><h2>${p.title}</h2><p class="muted">${p.dynasty} · ${p.author}</p><div class="row wrap mt">${[['next','补下一句'],['full','整首默写'],['paper','纸上默写']].map(([m,label])=>btn(label,'lit-mode',m===mode?'primary small':'small',`data-id="${p.id}" data-mode="${m}" aria-pressed="${m===mode}"`)).join('')}</div>${mode==='next'?`<div class="note-box mt"><span>上一句：${p.lines.at(-2)}<br>请写出紧接着的下一句。</span></div>`:'<p class="tip mt">回忆这首作品的全部句子。原文在核对前藏起来。</p>'}
  ${mode==='paper'?`<div class="empty"><h3>拿出纸笔，自己默一遍</h3><p>写好后再展开原文，逐句对照。</p>${btn('纸上写好了，看原文','lit-paper-reveal','primary',`data-id="${p.id}"`)}</div>${paperReveal===p.id?`<div class="feedback"><h3>原文对照</h3><div class="poem-original">${p.lines.map(l=>`<p>${l}</p>`).join('')}</div><p class="tip">检查漏字、错字和句子顺序。手写需要自己或家长批改。</p></div>`:''}`:`<form id="literacy-form" novalidate class="mt" data-poem="${p.id}" data-mode="${mode}"><label class="field" for="literacy-draft">${mode==='next'?'我的下一句':'我的整首默写'}<textarea id="literacy-draft" class="literacy-input" rows="5" maxlength="1000" data-key="${key}" aria-describedby="lit-help lit-error">${esc(text)}</textarea></label><p id="lit-help" class="tip">输入汉字后核对；标点和空格不计入文字核对。草稿仅保存在本机。</p><p id="lit-error" class="form-error" role="status"></p><p id="lit-save-status" class="tip" role="status">${text?'已读取本机草稿。':'写一点，再核对。'}</p><div class="practice-actions"><button type="submit" class="btn primary">核对默写</button></div></form>${checked?`<div class="feedback poem-test-feedback ${result.correct?'':'wrong'}" role="status"><h3>${result.correct?'文字核对一致':'还有字需要再检查'}</h3><p class="tip">对照自己的输入逐字检查；标点仍请自己检查。</p><div class="poem-original">${(mode==='next'?[p.lines.at(-1)]:p.lines).map(l=>`<p>${l}</p>`).join('')}</div></div>`:''}`}</section>`;
 }
 function picturePage(p){const key=draftKey('picture',p.id),text=draft(key);return `<div class="row mt">${back('pictures')}</div><div class="writing-workspace mt"><section class="card picture-study"><h2>${p.title}</h2><img class="story-image" src="${p.image}" alt="${esc(p.alt)}" width="800" height="480"><h3 class="mt-sm">先说清四件事</h3><ol class="writing-questions">${p.questions.map(q=>`<li>${q}</li>`).join('')}</ol><div class="row wrap">${p.words.map(w=>`<span class="chip">${w}</span>`).join('')}</div></section><section class="card"><label class="field" for="literacy-draft"><strong>我来写几句话</strong><textarea id="literacy-draft" class="literacy-input" rows="10" maxlength="1000" data-key="${key}" aria-describedby="picture-help lit-save-status">${esc(text)}</textarea></label><p id="picture-help" class="tip mt-sm">写清谁、在哪里、做什么，也可以写动作、心情和对话。每幅图最多1000字。</p><p id="lit-save-status" class="tip" role="status">${text?'已读取本机草稿。':'输入后会自动保存在本机。'}</p><p class="tip"><span id="lit-count">${[...text].length}</span> 字</p><h3 class="small-title mt">写完自己检查</h3><div class="writing-checks">${['人物和地点写清楚了','事情的经过写清楚了','句子通顺，有合适的标点'].map(t=>`<label><input type="checkbox">${t}</label>`).join('')}</div><details class="writing-sample mt"><summary>看看参考写法</summary><p class="tip">这是一种写法，不是标准答案。请用自己的观察和语言。</p><p>${p.sample}</p></details><p class="tip mt">这里提供写作练习与自查，不做作文自动评分。</p></section></div>`;}
 function radicalPage(){const values=Object.values(record().radicals);return `<div class="note-box mt">${icon('info')}<span>偏旁是构成合体字的部件；部首用于字典归类检字。偏旁不一定就是该字的部首。下面先认常见偏旁，再认识它的部首本形；查字时仍以所用字典的部首表为准。</span></div><div class="row between wrap mt"><p class="tip">已作答 ${values.reduce((n,r)=>n+r.attempts,0)} 次 · 答对 ${values.reduce((n,r)=>n+r.correct,0)} 次</p>${btn('开始偏旁辨认','lit-radical-start','primary')}</div><div class="grid three mt">${radicals.map(r=>`<article class="card radical-card"><div class="row"><strong class="radical-shape">${r.shape}</strong><div><h2>${r.name}</h2><p class="tip">认识部首本形：${r.parent}</p></div></div><p class="tip mt-sm">${r.hint}</p><div class="row wrap mt-sm">${r.examples.map(char=>btn(char,'lit-speak','small',`data-text="${char}" aria-label="慢听例字${char}"`)).join('')}</div></article>`).join('')}</div><p id="audio-status" class="listen-status mt" role="status">按钮播放完整例字音，不是偏旁的独立读音。</p>`;}
 function newQuiz(){const entry=shuffled(radicals)[0];quiz={entry,options:shuffled([entry.examples[0],...entry.others]),answer:null};}
 function radicalQuiz(){const {entry:r,options,answer}=quiz;return `<div class="row mt">${back('radicals')}</div><section class="card radical-exercise mt"><h2>哪个字带有这个偏旁？</h2><div class="radical-question">${r.shape}</div><p class="tip">${r.name} · 先观察字形，再选择。</p><div class="options">${options.map(char=>`<button class="option ${answer?(char===r.examples[0]?'correct':char===answer?'wrong':''):''}" data-action="lit-radical-answer" data-answer="${char}" ${answer?'disabled':''}>${char}</button>`).join('')}</div>${answer?`<div class="feedback ${answer===r.examples[0]?'':'wrong'}" role="status"><h3>${answer===r.examples[0]?'找对了！':'再看看偏旁的位置'}</h3><p>“${r.examples[0]}”带有${r.name} ${r.shape}。</p><p class="tip">${r.hint}</p>${btn('再练一个','lit-radical-start','primary mt-sm')}</div>`:''}</section>`;}
 function handle(action,d){
  if(action==='lit-tab'){paperReveal=null;visit(d.tab);}
  if(action==='lit-poem'){if(!poems.some(p=>p.id===d.id))return;visit(d.tab==='dictation'?'dictation':'poems',d.tab==='dictation'?'test':'poem',d.id);}
  if(action==='lit-mode'){paperReveal=null;visit('dictation','test',d.id,d.mode);}
  if(action==='lit-picture'){if(pictures.some(p=>p.id===d.id))visit('pictures','picture',d.id);}
  if(action==='lit-speak')void play(d.text,true);
  if(action==='lit-learned'&&poems.some(p=>p.id===d.id)){record().learned[d.id]=Date.now();if(persist())notify('熟读标记已保存在本机。');refresh();}
  if(action==='lit-paper-reveal'&&poems.some(p=>p.id===d.id)){paperReveal=d.id;refresh();}
  if(action==='lit-radical-start'){newQuiz();visit('radicals','quiz');}
  if(action==='lit-radical-answer'&&quiz&&!quiz.answer&&quiz.options.includes(d.answer)){quiz.answer=d.answer;const old=record().radicals[quiz.entry.id]||{attempts:0,correct:0};record().radicals[quiz.entry.id]={attempts:Math.min(100000,old.attempts+1),correct:Math.min(100000,old.correct+(d.answer===quiz.entry.examples[0]?1:0)),updated:Date.now()};persist();refresh();}
 }
 function bind(){let composing=false;const el=document.querySelector('#literacy-draft');if(el){const saveDraft=()=>{if(composing)return;results.delete(el.dataset.key);document.querySelector('.poem-test-feedback')?.remove();el.removeAttribute('aria-invalid');const error=document.querySelector('#lit-error');if(error)error.textContent='';record().drafts[el.dataset.key]={text:el.value.slice(0,1000),updated:Date.now()};const ok=persist();document.querySelector('#lit-save-status').textContent=ok?'已自动保存在本机。':'暂未保存成功，请先复制文字保留。';const count=document.querySelector('#lit-count');if(count)count.textContent=[...el.value].length;el.style.height='auto';el.style.height=Math.max(180,el.scrollHeight)+'px';};el.addEventListener('compositionstart',()=>composing=true);el.addEventListener('compositionend',()=>{composing=false;saveDraft();});el.addEventListener('input',saveDraft);el.style.height=Math.max(180,el.scrollHeight)+'px';}
  document.querySelector('#literacy-form')?.addEventListener('submit',e=>{e.preventDefault();if(composing)return;const form=e.currentTarget,p=poems.find(p=>p.id===form.dataset.poem),mode=form.dataset.mode,input=form.querySelector('textarea');if(!input.value.trim()){document.querySelector('#lit-error').textContent='先输入自己的默写内容，再核对原文。';input.setAttribute('aria-invalid','true');input.focus();return;}const key=draftKey('poem',p.id,mode);results.set(key,{text:input.value,...checkPoem(input.value,mode==='next'?[p.lines.at(-1)]:p.lines)});refresh();document.querySelector('.feedback')?.scrollIntoView({block:'nearest'});});
 }
 return {render,handle,bind};
}
